/**
 * Private storage for uploaded agreement files.
 *
 * Netlify Blobs has no access control of its own and is never exposed
 * publicly here: the only way to read a document is the API's download
 * route, which serves a blob key it has just found through a row-level
 * security filtered query. Keys are generated by the server and never taken
 * from a request.
 */

export interface StoredDocument {
  data: ArrayBuffer;
}

export interface DocumentStore {
  put(key: string, data: ArrayBuffer, metadata: Record<string, string>): Promise<void>;
  get(key: string): Promise<StoredDocument | null>;
  delete(key: string): Promise<void>;
}

/**
 * Site-wide Blobs stores are shared by every deploy context, so a deploy
 * preview writing to the production store would put preview uploads next to
 * real ones. Each context therefore gets its own store. A preview's database
 * branch starts as a copy of production, so production document rows show up
 * there, but their files are not readable from the preview.
 */
export function documentStoreName(context = process.env.CONTEXT): string {
  return context && context !== "production" ? `agreement-documents-${context}` : "agreement-documents";
}

export function documentKey(agreementId: string, documentId: string): string {
  return `agreements/${agreementId}/${documentId}`;
}

export async function createNetlifyDocumentStore(): Promise<DocumentStore> {
  const { getStore } = await import("@netlify/blobs");
  const store = getStore({ name: documentStoreName(), consistency: "strong" });
  return {
    async put(key, data, metadata) {
      await store.set(key, data, { metadata });
    },
    async get(key) {
      const data = await store.get(key, { type: "arrayBuffer" });
      return data === null ? null : { data };
    },
    async delete(key) {
      await store.delete(key);
    },
  };
}

/** In-memory store for tests and local runs without Netlify. */
export function createMemoryDocumentStore(): DocumentStore & { keys(): string[] } {
  const entries = new Map<string, ArrayBuffer>();
  return {
    async put(key, data) {
      entries.set(key, data.slice(0));
    },
    async get(key) {
      const data = entries.get(key);
      return data ? { data: data.slice(0) } : null;
    },
    async delete(key) {
      entries.delete(key);
    },
    keys: () => [...entries.keys()],
  };
}
